class Solution {
    /**
    Check if in given list of numbers, are any two numbers closer to each other than given threshold.
    >>> hasCloseElements(Arrays.asList(1.0, 2.0, 3.0), 0.5)
    false
    >>> hasCloseElements(Arrays.asList(1.0, 2.8, 3.0, 4.0, 5.0, 2.0), 0.3)
    true
     */
    public boolean hasCloseElements(List<Double> numbers, double threshold) {

    Collections.sort(numbers); // Sort the list to make comparison easier
    for (int i = 0; i < numbers.size() - 1; i++) {
        if (numbers.get(i + 1) - numbers.get(i) < threshold) {
            return true; // Found two numbers closer than the threshold
        }
    }
    return false; // No two numbers are closer than the threshold

