class Solution {
    /**
    Test if given string is a palindrome
     */
    public boolean isPalindrome(String string) {
        int i = 0;
        int j = string.length() - 1;
        while (i < j) {
            if (string.charAt(i)!= string.charAt(j)) {
                return false;
            }
            i++;
            j--;
        }
        return true;
    }
    /**
    Find the shortest palindrome that begins with a supplied string.
    Algorithm idea is simple:
    - Find the longest postfix of supplied string that is a palindrome.
    - Append to the end of the string reverse of a string prefix that comes before the palindromic suffix.
    >>> makePalindrome("")
    ""
    >>> makePalindrome("cat")
    "catac"
    >>> makePalindrome("cata")
    "catac"
     */
    public String makePalindrome(String string) {

        int i = 0;
        int j = string.length() - 1;
        while (i < j) {
            if (string.charAt(i)!= string.charAt(j)) {
                return false;
            }
            i++;
            j--;
        }
        return true;
    }

    // Function to generate the shortest palindrome starting with the given string
    public String makePalindrome(String string) {
        // Check if the string is empty, in which case return an empty string
        if(string.isEmpty())
            return "";

        // Find the longest palindromic suffix
        int j = string.length();
        while (!isPalindrome(string.substring(j-1)))
            j--;

        // Append the reverse of the prefix to the string
        return string + new StringBuilder(string.substring(0, j-1)).reverse().toString();

