     */
    public int howManyTimes(String string, String substring) {

    if (substring.length() == 0) {
        return 0;
    }
    int count = 0;
    int index = 0;
    while ((index = string.indexOf(substring, index)) != -1) {
        count++;
        index++; // Move to the next character to allow overlapping matches
    }
    return count;

