        double lowerBound = -100;
        double upperBound = 100;
        double precision = 0.00001;

        while (upperBound - lowerBound > precision) {
            double mid = (lowerBound + upperBound) / 2;
            double polyValue = poly(xs, mid);

            if (polyValue == 0) {
