    for (int i = 0; i < l.size() - 2; i++) { // iterate through the list
        int left = i + 1; // initialize left pointer
        int right = l.size() - 1; // initialize right pointer
        while (left < right) { // loop until left pointer is less than right pointer
            int sum = l.get(i) + l.get(left) + l.get(right); // calculate the sum of the three elements
