    matchParens(Arrays.asList(")", ")")) == "No"
     */
    public String matchParens(List<String> lst) {

        int balance = 0;
        for (String s : lst) {
            for (char c : s.toCharArray()) {
                if (c == '(') {
                    balance++;
                } else {
                    balance--;
                    if (balance < 0) {
                        return "No";
                    }
                }
            }
        }
        return balance == 0 ? "Yes" : "No";

