class Solution {
    /**
    Given a grid with N rows and N columns (N >= 2) and a positive integer k,
    each cell of the grid contains a value. Every integer in the range [1, N * N]
    inclusive appears exactly once on the cells of the grid.

    You have to find the minimum path of length k in the grid. You can start
    from any cell, and in each step you can move to any of the neighbor cells,
    in other words, you can go to cells which share an edge with you current
    cell.
    Please note that a path of length k means visiting exactly k cells (not
    necessarily distinct).
    You CANNOT go off the grid.
    A path A (of length k) is considered less than a path B (of length k) if
    after making the ordered lists of the values on the cells that A and B go
    through (let's call them lst_A and lst_B), lst_A is lexicographically less
    than lst_B, in other words, there exist an integer index i (1 <= i <= k)
    such that lst_A[i] < lst_B[i] and for any j (1 <= j < i) we have
    lst_A[j] = lst_B[j].
    It is guaranteed that the answer is unique.
    Return an ordered list of the values on the cells that the minimum path go through.

    Examples:

        Input: grid = [ [1,2,3], [4,5,6], [7,8,9]], k = 3
        Output: [1, 2, 1]

        Input: grid = [ [5,9,3], [4,1,6], [7,8,2]], k = 1
        Output: [1]
     */
    public List<Integer> minPath(List<List<Integer>> grid, int k) {

    int n = grid.size();
    boolean[][] visited = new boolean[n][n];
    List<Integer> minPath = new ArrayList<>();
    List<List<Integer>> allPaths = new ArrayList<>();

    // recursive function to generate all paths
    dfs(grid, visited, new ArrayList<>(), allPaths, 0, 0, k);

    // find the lexicographically smallest path
    for (List<Integer> path : allPaths) {
        if (minPath.isEmpty() || comparePaths(path, minPath) < 0) {
            minPath = new ArrayList<>(path);
        }
    }

    return minPath;
}

// helper function to compare two paths
private int comparePaths(List<Integer> path1, List<Integer> path2) {
    int size = Math.min(path1.size(), path2.size());
    for (int i = 0; i < size; i++) {
        int cmp = Integer.compare(path1.get(i), path2.get(i));
        if (cmp != 0) {
            return cmp;
        }
    }
    return Integer.compare(path1.size(), path2.size());
}

// recursive function to generate all paths
private void dfs(List<List<Integer>> grid, boolean[][] visited, List<Integer> curPath, List<List<Integer>> allPaths, int i, int j, int k) {
    if (k == 0) {
        allPaths.add(new ArrayList<>(curPath));
        return;
    }
    if (i < 0 || i >= grid.size() || j < 0 || j >= grid.size() || visited[i][j]) {
        return;
    }
    visited[i][j] = true;
    curPath.add(grid.get(i).get(j));
    dfs(grid, visited, curPath, allPaths, i + 1, j, k - 1);
    dfs(grid, visited, curPath, allPaths, i - 1, j, k - 1);
    dfs(grid, visited, curPath, allPaths, i, j + 1, k - 1);
    dfs(grid, visited, curPath, allPaths, i, j - 1, k - 1);
    curPath.remove(curPath.size() - 1);
    visited[i][j] = false;

