class Solution {
    /**
    Create a function which takes a string representing a file's name, and returns
    "Yes" if the the file's name is valid, and returns "No" otherwise.
    A file's name is considered to be valid if and only if all the following conditions
    are met:
    - There should not be more than three digits ('0'-'9') in the file's name.
    - The file's name contains exactly one dot '.'
    - The substring before the dot should not be empty, and it starts with a letter from
    the latin alphapet ('a'-'z' and 'A'-'Z').
    - The substring after the dot should be one of these: ["txt", "exe", "dll"]
    Examples:
    file_name_check("example.txt") # => "Yes"
    file_name_check("1example.dll") # => "No" (the name should start with a latin alphapet letter)
     */
    public String filenameCheck(String file_name) {

    int digitCount = 0;
    int dotCount = 0;
    int startIndex = 0;
    String extension = "";

    // Count the number of digits and dots in the file name
    for (int i = 0; i < file_name.length(); i++) {
        char c = file_name.charAt(i);
        if (Character.isDigit(c)) {
            digitCount++;
        } else if (c == '.') {
            dotCount++;
            startIndex = i + 1;
        }
    }

    // Check if there are exactly one dot and no more than three digits
    if (dotCount != 1 || digitCount > 3) {
        return "No";
    }

    // Check if the name starts with a letter and the extension is one of the allowed ones
    String namePart = file_name.substring(0, startIndex);
    if (namePart.isEmpty() || !Character.isLetter(namePart.charAt(0))) {
        return "No";
    }
    extension = file_name.substring(startIndex);
    String[] validExtensions = {"txt", "exe", "dll"};
    boolean validExtension = false;
    for (String validExt : validExtensions) {
        if (extension.equals(validExt)) {
            validExtension = true;
            break;
        }
    }
    if (!validExtension) {
        return "No";
    }

    // If all checks pass, the file name is valid
    return "Yes";

