    public int doAlgebra(List<String> operator, List<Integer> operand) {

        Stack<Integer> stack = new Stack<>();

        for (int i = 0; i < operand.size(); i++) {
            stack.push(operand.get(i));
            if (i < operator.size()) {
                int right = stack.pop();
                int left = stack.pop();
                switch (operator.get(i)) {
                    case "+":
                        stack.push(left + right);
                        break;
                    case "-":
                        stack.push(left - right);
                        break;
                    case "*":
                        stack.push(left * right);
                        break;
                    case "/":
                        stack.push(left / right);
                        break;
                    case "**":
                        stack.push((int) Math.pow(left, right));
                        break;
                    default:
                        throw new IllegalArgumentException("Invalid operator: " + operator.get(i));
                }
            }
        }

        return stack.pop();

